<script lang="ts">
 import {untrack} from 'svelte';import Modal from './Modal.svelte';import Feedback from './Feedback.svelte';import {Button} from '#lib/components/ui/button/index.ts';import {adminClinicsApi} from '#lib/api/admin/clinics.ts';import {apiMessage} from '#lib/admin/scheduling.ts';import type {ApiStaff,ApiStaffRole,ApiStaffCreate} from '#lib/types/clinic.ts';
 let {open=$bindable(false),facilityId,staff=null,onSaved}:{open?:boolean;facilityId:string;staff?:ApiStaff|null;onSaved:()=>void}=$props();
 const roles:Record<ApiStaffRole,string>={doctor:'醫師',nurse:'護理師',receptionist:'櫃檯',admin:'行政',beautician:'美容師',therapist:'治療師'};
 let current=$state<ApiStaff|null>(null),name=$state(''),phone=$state(''),email=$state(''),role=$state<ApiStaffRole>('doctor'),active=$state(true),visible=$state(true),bookable=$state(true),department=$state(''),license=$state(''),licenseType=$state(''),nhi=$state(''),education=$state(''),experience=$state(''),specialties=$state(''),certifications=$state(''),years=$state<number|undefined>(),busy=$state(false),error=$state(''),message=$state('');
 $effect(()=>{if(!open)return;const s=staff;untrack(()=>{current=s;name=s?.name??'';phone=s?.phone??'';email=s?.email??'';role=s?.role??'doctor';active=s?.is_active??true;visible=s?.is_public_visible??true;bookable=s?.is_bookable??true;department=s?.department??'';license=s?.license_number??'';licenseType=s?.license_type??'';nhi=s?.nhi_provider_id??'';education=s?.education?.join('\n')??'';experience=s?.experience?.join('\n')??'';specialties=s?.main_specialties?.join('\n')??'';certifications=s?.certifications?.join('\n')??'';years=s?.experience_years;error='';message='';});});
 const lines=(s:string)=>s.split('\n').map(x=>x.trim()).filter(Boolean);
 async function save(e:SubmitEvent){e.preventDefault();busy=true;error='';const data:ApiStaffCreate={name:name.trim(),phone:phone.trim(),email:email.trim(),role,is_public_visible:visible,is_bookable:bookable,...(role==='doctor'?{department,license_number:license,license_type:licenseType,nhi_provider_id:nhi,education:lines(education),experience:lines(experience),main_specialties:lines(specialties)}:{}),...(['beautician','therapist'].includes(role)?{certifications:lines(certifications),experience_years:years??0}:{})};try{current=current?await adminClinicsApi.staff.update(facilityId,current.id,{...data,is_active:active}):await adminClinicsApi.staff.create(facilityId,data);onSaved();open=false;}catch(e){error=apiMessage(e,'人員資料儲存失敗');}finally{busy=false;}}
 async function upload(e:Event){const input=e.currentTarget as HTMLInputElement,file=input.files?.[0];if(!file||!current)return;busy=true;error='';try{current=await adminClinicsApi.staff.uploadAvatar(facilityId,current.id,file);onSaved();message='照片已更新';}catch(e){error=apiMessage(e,'照片上傳失敗');}finally{busy=false;input.value='';}}
</script>
<Modal bind:open title={current?'人員檔案與編輯':'新增人員'} description="維護聯絡方式、公開資料與預約資格。學經歷及證照每行填寫一項。" {busy}><form onsubmit={save} class="space-y-5"><Feedback {error} {message}/><fieldset disabled={busy} class="space-y-4">{#if current}<div class="flex flex-wrap items-center gap-3">{#if current.avatar_url}<img src={current.avatar_url} alt={current.name} class="size-20 rounded-xl object-cover"/>{/if}<label>上傳人員照片<input type="file" accept="image/jpeg,image/png,image/webp" onchange={upload}/></label></div>{:else}<p class="text-sm text-muted-foreground">先儲存人員，再開啟檔案上傳照片。</p>{/if}<div class="grid gap-4 sm:grid-cols-2"><label>姓名<input bind:value={name} required/></label><label>角色<select aria-label="角色" bind:value={role}>{#each Object.entries(roles) as [key,label] (key)}<option value={key}>{label}</option>{/each}</select></label><label>電話<input type="tel" bind:value={phone}/></label><label>電子郵件<input type="email" bind:value={email}/></label></div><div class="flex flex-wrap gap-4">{#if current}<label><input type="checkbox" bind:checked={active}/>啟用人員</label>{/if}<label><input type="checkbox" bind:checked={visible}/>公開顯示</label><label><input type="checkbox" bind:checked={bookable}/>開放預約</label></div>{#if role==='doctor'}<div class="grid gap-4 sm:grid-cols-2"><label>科別<input bind:value={department}/></label><label>執照號碼<input bind:value={license}/></label><label>證照類別<input bind:value={licenseType}/></label><label>健保醫事人員代碼<input bind:value={nhi}/></label></div><label>學歷<textarea bind:value={education}></textarea></label><label>經歷<textarea bind:value={experience}></textarea></label><label>主要專長<textarea bind:value={specialties}></textarea></label>{:else if ['beautician','therapist'].includes(role)}<label>證照<textarea bind:value={certifications}></textarea></label><label>服務年資<input type="number" min="0" max="100" bind:value={years}/></label>{/if}{#if current}<p class="text-xs text-muted-foreground">建立日期：{current.created_at?.slice(0,10)} · 最後登入：{current.last_login??'尚未登入'}</p>{/if}</fieldset><div class="flex justify-end gap-2"><Button variant="outline" disabled={busy} onclick={()=>open=false}>取消</Button><Button type="submit" disabled={busy}>{busy?'儲存中…':'儲存人員'}</Button></div></form></Modal>
